        [255662] = "While this is in your possession, you are able to safely interact with unstable mana found throughout Shen'dralas.",
        [255663] = "A small glowing stone empowered with the magical essence of Skywall. It is often used as both a currency and a source of magical energy on Zephras Isle.",
