        [255878] = "It hums with power. You feel emboldened in your journey while holding this.",
        [255945] = "An evil presence can be felt within.",
        [256057] = "An incredibly rare crystal that originated from another world. Its numerous uses have only just begun to be discovered.",
        [257029] = "An old satchel containing several unbound books of loose parchment.",
        [257126] = "It has the glow of life, but no warmth.",
        [257348] = "Contains the very spark of creativity.",
        [257685] = "Packed to the brim with totems used by the centaur as currency. Delivering this to one of the rivaling clans is sure to earn their favor.",
        [257808] = "Letters and packages for delivery to Everlook.",
        [257809] = "Letters and packages for delivery to Mount Hyjal.",
        [258296] = "A single vial of this mystical water can bring about a torrent of rainfall.",
        [258526] = "The journal is filled with atmospheric weather and rocket staging information.",
        [258530] = "Covered in the guts of countless swamp fish.",
        [258771] = "You can't help but wonder what the Nightclaw plan to do with all these ears.",
        [258774] = "The notes are written in multiple colors of ink, a sign of a long study.",
        [259226] = "Simply iron ore, though bound to the spirit realm.",
        [259229] = "Reveals Ghostly Iron Deposits while in your inventory. Also serves as a regular mining pick!",
        [259461] = "Oh no...",
        [259990] = "This was a troll's tusk ring. It was clearly well-loved once, but that was long ago.",
        [260167] = "Inscribed on the boot tongue: ...16, 23...",
        [260236] = "A hastily scrawled list of locations for prospecting.",
        [260237] = "Whether it is actually the blood of the fallen god is unclear, but what is certain is how eager it seems to escape the vial.",
        [260244] = "Do quilboar even like flowers?",
        [260245] = "Its beauty is a stark contrast from the gardens in which it grew.",
        [260247] = "Once an enchanted necklace that sustained life in the gardens of Shen'dralas. Whatever magic it once contained has since been depleted.",
        [260307] = "Neither snow nor rain nor heat nor gloom of night...",
        [260347] = "Most of the pages are missing.",
        [260518] = "Gimashi's findings on draenethyst; organized and edited for clarity.",
        [260784] = "SAF-T brand tabs make it SAF to hand out dynamite to all your friends!",
        [260792] = "Easy to throw, and SAF-T too!",
        [260793] = "SAF-T Brand bombs *almost* never blow up in your hands (or your paws!)",
        [260796] = "SAF-T Padding prevents those easy throwing accidents.",
        [260798] = "If it's easy to throw, it's not SAF-T!",
        [260799] = "Do you know where your Sheep is?! SAF-T Knows.",
        [260800] = "Guaranteed to blow up only where it's SAF!",
        [260801] = "Guaranteed not to burn!",
        [260802] = "Thro mo mo tar!",
        [260803] = "Who needs safety when it's this easy to throw?",
        [260804] = "Extra padding for SAF-T!",
        [260805] = "S. A. F. T. B. O. M. B. SAF-T. Bomb.",
        [260806] = "SAF-T means not getting caught.",
        [260808] = "EZ to use and almost never misfires!",
        [260809] = "Tru-Trigger frags enemies, not in your hands.",
        [260810] = "SAF-T in case you need to jump.",
        [260811] = "It's got everything: a spanner, a wrench, a hammer... even a mining pick.",
        [260813] = "Prevents accidental oxygen exposure. That wouldn't be SAF.",
        [260814] = "SAF-T isn't dense. It's clever!",
        [260815] = "Encase your explosives in EZ to Thro thorium-plated shells.",
        [260816] = "Anyone can use grenades with EZ-Thro!",
        [260817] = "So EZ, you can Thro it in the dark.",
        [260821] = "Not only combining Goblin and Gnome tech, but also combining plans from the EZ-Thro and SAF-T corporations. Who knows if this will even work?",
