        [271770] = "A standard-issue kit with all the tools necessary for exploring and categorizing newly explored areas.",
        [271771] = "A gem that is cool to the touch and hums gently. Strangely, no light seems to filter through it.",
        [271870] = "A useless lump of coal.",
        [271880] = "A menacing glow emanates from the strange carving.",
        [271894] = "A gem that is hot to the touch and hums gently. It seems to emit a small amount of light, almost like the flickering of fire.",
        [271898] = "A gem that hums gently and seems to emit a static charge. On its own it emits a tiny amount of light and small flashes can be seen right under the surface, as if a tiny storm was trapped within.",
        [271902] = "A gem that seems to emit the slightest of fumes and hums gently. It burns slightly to hold, but when dropped on the ground, new grass sprouts around it.",
        [271912] = "A gem that seems to collect condensation on the surface making it perpetually wet and hums gently. When turned in the light, it looks as if there is water trapped within the crystal itself.",
