        [272124] = "A compilation of the translated workings by Loremaster Dibbs, recounting the tale of the lost troll city, I'lalai the Drowned City.",
        [272151] = "This dented and damaged crate looks like it quite literally fell off the back of a zeppelin.",
        [272313] = "The hilt is unfathomably ancient, but the metal that peeks through the dust and grime still shines brightly. This weapon was clearly a masterwork before it was broken.",
        [272314] = "The liquid inside the vial seems to churn violently, and sticks to the glass in a way that suggests a certain amount of elasticity.",
