        [286263] = "May the Holy Light protect us on our expedition to the frozen north.",
        [286264] = "I really wish you mages would get your heads out from inside your own... books.",
        [286265] = "May my sisters realize their full potential, the name Windrunner known as a result of their deeds.",
        [286266] = "Grant me the strength to accept the things that I cannot change, the courage to change the things I can, and the wisdom to know the difference.",
        [286267] = "Oh, why won't you notice me? Abbendis, I would follow you anywhere. I wish you would notice me...",
        [286268] = "I pray that when the time comes, I will have the strength to thwart the forces beyond the gate.",
        [286270] = "How does this fountain even work? I wonder if I could make one.",
        [286271] = "Turalyon and Alleria, wherever you are, may you be well.",
        [286272] = "May my son Arthas always act in the best interest of his people.",
        [286273] = "Where's Illidan?",
        [286274] = "<You sense the ringing of three tones in your head, the third barely audible under the others' din.>",
        [286275] = "I hope that my father and brothers outlive me. I'll not make much of a king.",
        [286279] = "I wish I would grow up, it feels like I've been 10 for years.",
        [286280] = "Young Arthas must learn patience to temper his power. I will pray that he one day learns how to lead with care rather than force.",
        [286281] = "Already, I've a kingdom in my prospects, a land to rule. What to ask for? Perhaps a frozen scone...",
        [286283] = "I wish someday to retire to my own tidy little estate, with a bunch of pet dogs to keep me company.",
        [286284] = "Brann Bronzebeard was here.",
        [286287] = "Sometimes... I wish someone would come along and just give me a big, long hug.",
        [286288] = "Arthas, my love, please come back to me.",
        [286290] = "Listen, little wishing fountain. You'll give me all your power if you know what's good for you.",
        [286291] = "I hope my sisters and I can grow up and get married together. This coin appears to be very old.",
        [286292] = "It is my wish that my dear Taelan will grow strong enough to defend the people he cares for.",
        [286293] = "I wish to know how you survived my wrath, little fountain.",
        [286294] = "Explain my dreams, little fountain. Why must I always be viewing my kin from above and moving them like pawns?",
        [286298] = "It seems my moonlighting days as a postal worker are coming to an end.",
        [286299] = "Grom, may you rest well, old friend.",
        [286300] = "This doesn't make sense. Why am I putting a coin in a fountain?",
        [286302] = "The amount of coins shining in the pool. Maybe no one will notice if I take just one.",
        [286304] = "Wish I had that cousin of mine's duty to do nothing more than lug wood around carelessly...",
        [286306] = "I wish Captain Sanders would hurry up with my shipment of wine.",
        [286307] = "I wish for happiness and acceptance for my daughter. She feels so out of place here...",
        [286308] = "Can I have a more comfortable saddle? My hindquarters ache.",
        [286309] = "I hope a troll dies, right... NOW.",
        [286310] = "Being a rogue is hard work. Someday I hope to pursue my life's one true passion...",
        [286311] = "I hope I end up in another book eventually.",
        [286312] = "I wish I had my father back...",
        [286313] = "I wish I'd kept that coin...",
        [286314] = "I wish people would stop knocking my toys off the shelf.",
        [286315] = "I could have used this copper for something productive. Perhaps something with string and a machine.",
        [286316] = "It's not even magical here.",
        [286317] = "How does a tavern run out of ale!",
        [286318] = "I miss my sword and shield. I feel so naked without my sword and shield.",
        [286327] = "Here you go, Nozdormu. What was I supposed to do after this?",
        [286328] = "How do I prove they copied us with this fountain?",
        [286568] = "Taken from a hyena that consumed anything, or anyone.",
        [287505] = "Kyle would delight in taking a bite out of this succulent treat!",
        [287958] = "Fragmented remnants of the construct, refracting light like a kaleidoscope.",
        [287959] = "Fragmented remnants of the construct, refracting light like a kaleidoscope.",
        [285094] = "Still surprisingly durable.",
        [282706] = "There's no questioning how Foulbelly earned that name.",
    },
